function ERASED_BITS(f, domain):
    if domain is empty: error
    n <- |domain|
    image <- empty set
    for x in domain:
        insert f(x) into image
    return log2(n) - log2(|image|)

function KERNEL_LAW_VERIFY(elements, f, id_H):
    order <- |elements|
    image <- { f(x) : x in elements }
    kernel <- { x in elements : f(x) = id_H }
    counting_ok <- (|image| * |kernel| = order)
    erased <- log2(order) - log2(|image|)
    law_ok <- (erased approx log2(|kernel|))
    return (counting_ok and law_ok, erased, log2(|kernel|))

function COMPOSITION_SERIES_LEDGER(orders):  // orders = [|G_0|,...,1]
    total <- 0
    for (big, small) in consecutive_pairs(orders):
        assert small divides big
        total <- total + log2(big / small)
    return total   // equals log2(|G_0|)

